  [T('De 11 à 20',`<table class="ptable"><tr><td>11 ${en('eleven')}</td><td>12 ${en('twelve')}</td><td>13 ${en('thirteen')}</td><td>14 ${en('fourteen')}</td><td>15 ${en('fifteen')}</td></tr><tr><td>16 ${en('sixteen')}</td><td>17 ${en('seventeen')}</td><td>18 ${en('eighteen')}</td><td>19 ${en('nineteen')}</td><td>20 ${en('twenty')}</td></tr></table><p>${en('How old are you?')} – ${en('I’m seven.')} (J’ai sept ans.)</p>`)],
